                  '<tbody>' + rows + '</tbody>' +
                  '</table>' +
                  '</div>',
              })
            },
          },
        ]
      }
    ],
  }
}

function setupForm({ doc, call, router, updateField, createToast, $dialog, toast, deleteDoc }) {
  // small helper to render a combobox (input + UL list) using frappe-ui classes
  function comboboxHtml(id, placeholder) {
    return `
<div style="position:relative;">
  <input id="${id}_input" autocomplete="off" placeholder="${placeholder}" class="text-base rounded h-7 py-1.5 pl-2 pr-7 border border-[--surface-gray-2] bg-surface-gray-2 placeholder-ink-gray-4 w-full" />
  <input type="hidden" id="${id}_value" />
  <ul id="${id}_list" role="listbox" aria-labelledby="${id}_input" class="my-1 max-h-[12rem] overflow-y-auto p-1.5 pt-0" style="display:none;position:absolute;left:0;right:0;z-index:6000;background:var(--surface-modal,#fff);border-radius:6px;box-shadow:0 10px 25px rgba(0,0,0,0.08);margin-top:6px;">
    <!-- options injected here -->
  </ul>
</div>
`;
  }

  // attach behavior to a combobox: items = [{label, value}, ...]
  function attachCombobox(id, items, initialValue) {
    const input = document.getElementById(id + "_input");
    const list = document.getElementById(id + "_list");
    const hidden = document.getElementById(id + "_value");
    if (!input || !list || !hidden) return;
    let filtered = items.slice();
    let focusIndex = -1;

    function escapeHtml(s) {
      return String(s == null ? "" : s)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;");
    }

    function renderList() {
      list.innerHTML = filtered
        .map(
          (it, i) =>
            `<li class="flex cursor-pointer items-center rounded px-2.5 py-1.5 text-base" role="option" data-idx="${i}" data-value="${escapeHtml(
              it.value
            )}" tabindex="-1"><div class="flex-1 truncate text-ink-gray-7">${escapeHtml(it.label)}</div></li>`
        )
        .join("");
      list.style.display = filtered.length ? "block" : "none";
      focusIndex = -1;
    }

    function setSelection(it) {
      if (!it) return;
      input.value = it.label;
      hidden.value = it.value;
      list.style.display = "none";
      input.dispatchEvent(new Event("change", { bubbles: true }));
    }

    // initialize from initialValue (can be value or label)
    if (initialValue) {
      const found = items.find((it) => it.value === initialValue || it.label === initialValue);
      if (found) setSelection(found);
      else {
        input.value = initialValue;
        hidden.value = "";
      }
    }

    input.addEventListener("input", () => {
      const q = input.value.trim().toLowerCase();
      filtered = items.filter((it) => it.label.toLowerCase().includes(q));
      renderList();
    });

    input.addEventListener("focus", () => {
      filtered = items.slice();
      renderList();
    });

    input.addEventListener("keydown", (e) => {
      if (list.style.display === "none") return;
      const nodes = Array.from(list.querySelectorAll("li"));
      if (e.key === "ArrowDown") {
        e.preventDefault();
        focusIndex = Math.min(focusIndex + 1, nodes.length - 1);
        nodes[focusIndex]?.focus();
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        focusIndex = Math.max(focusIndex - 1, 0);
        nodes[focusIndex]?.focus();
      } else if (e.key === "Enter") {
        e.preventDefault();
        if (focusIndex >= 0 && nodes[focusIndex]) {
          nodes[focusIndex].click();
        } else if (nodes[0]) {
          nodes[0].click();
        }
      } else if (e.key === "Escape") {
        list.style.display = "none";
      }
    });

    // delegate click
    list.addEventListener("click", (ev) => {
      const li = ev.target.closest("li");
      if (!li) return;
      const idx = parseInt(li.dataset.idx, 10);
      const it = filtered[idx];
      if (!it) return;
      setSelection(it);
      input.focus();
    });

    // click outside to close
    const onDocClick = (ev) => {
      if (!input || !list) return;
      if (!input.contains(ev.target) && !list.contains(ev.target)) {
        list.style.display = "none";
      }
    };
    document.addEventListener("click", onDocClick);

    // expose a small API to set value programmatically
    return {
      setValue(v) {
        const found = items.find((it) => it.value === v || it.label === v);
        if (found) setSelection(found);
        else {
          input.value = v;
          hidden.value = v;
        }
      },
      destroy() {
        document.removeEventListener("click", onDocClick);
      },
    };
  }

