  // Async: look up customer by custom_crm_organization and return actions
  async function resolveActions() {
    try {
      const customers = await call("frappe.client.get_list", {
        doctype: "Customer",
        filters: { custom_crm_organization: doc.name },
        fields: ["name"],
        limit: 1,
      });
      const linkedCustomer = customers && customers.length ? customers[0].name : null;

      if (linkedCustomer) {
        return [
          {
            label: "View Customer",
            onClick: () => {
              window.open(`/app/customer/${encodeURIComponent(linkedCustomer)}`, "_blank");
